async function handleStore<T>(mode:IDBTransactionMode,work:(store:IDBObjectStore)=>IDBRequest<T>):Promise<T>{return new Promise((resolve,reject)=>{const opening=indexedDB.open('document-workspace-handles',1);opening.onupgradeneeded=()=>opening.result.createObjectStore('handles');opening.onerror=()=>reject(opening.error);opening.onsuccess=()=>{const db=opening.result;const tx=db.transaction('handles',mode);const request=work(tx.objectStore('handles'));request.onerror=()=>reject(request.error);tx.oncomplete=()=>{db.close();resolve(request.result);};tx.onabort=()=>{db.close();reject(tx.error);};};});}
