 async function load():Promise<void>{if(busy)return;busy=true;content.replaceChildren(el('p',c.loading));try{let pending=pendingEvidence.get(key);if(!pending){pending=api<RecordedEvidence>('/api/runs/'+encodeURIComponent(runId)+'/documents/'+encodeURIComponent(fingerprint)+'/evidence').then(value=>{if(value.runId!==runId||value.fingerprint!==fingerprint)throw new Error(c.evidenceMismatch);if(terminalEvidence(value))evidenceCache.set(key,value);else evidenceCache.delete(key);return value;}).finally(()=>pendingEvidence.delete(key));pendingEvidence.set(key,pending);}const value=await pending;display(value);}catch(error){content.replaceChildren(button(c.evidenceReload,load));showError(error);}finally{busy=false;}}
