function help(main:HTMLElement):void{intro(main,c.helpTitle);for(const [title,body] of c.helpSteps)main.append(section(title,body));const wrong=section(c.wrongTitle);wrong.append(table([c.status,c.details],c.wrongRows.map(row=>[...row])));main.append(wrong);const faq=section(c.faqTitle);for(const [q,a]of c.faq){const d=el('details');d.append(el('summary',q),el('p',a));faq.append(d);}main.append(faq);}
async function render():Promise<void>{const generation=++renderId;if(poll)clearTimeout(poll);if(waitExpiry)clearTimeout(waitExpiry);const [requested,run]=location.hash.slice(1).split('/');page=Object.hasOwn(c.nav,requested)?requested as Page:decodeURIComponent(location.pathname).endsWith('How It Works.html')?'help':location.pathname.replace(/\/$/,'')==='/health'?'health':'home';activeRun=run?decodeURIComponent(run):(['build','correct'].includes(page)?localStorage.getItem('workspace-active-run')??'':'');if(activeRun)localStorage.setItem('workspace-active-run',activeRun);root.replaceChildren();const skip=el('a',c.skip,'skip');skip.href='#content';root.append(skip);const header=el('header');const bar=el('div',undefined,'bar');const brandBlock=el('div',undefined,'brand-block');const brandIcon=el('span',undefined,'brand-icon');brandIcon.append(icon('file'));brandBlock.append(brandIcon,el('div',c.product,'brand'));bar.append(brandBlock,el('p',c.workspaceTools,'nav-caption'));const nav=el('nav');nav.setAttribute('aria-label',c.navigationLabel);for(const [key,label]of Object.entries(c.nav)){if(key==='health')nav.append(el('span',c.workspaceSupport,'nav-caption nav-divider'));const link=el('a',label);link.href=`#${key}`;if(key===page)link.setAttribute('aria-current','page');link.prepend(icon(key));nav.append(link);}bar.append(nav,button(c.theme,()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('theme',next);}));bar.append(el('p',c.privacyFootnote,'sidebar-footnote'));header.append(bar);const main=el('main');main.id='content';main.dataset.page=page;main.setAttribute('aria-live','polite');const toolbar=el('div',undefined,'page-toolbar');toolbar.append(el('span',c.nav[page],'page-location'));const systemLink=el('a',c.loading,'system-status');systemLink.href='#health';systemLink.setAttribute('aria-label',c.systemStatus);toolbar.append(systemLink);main.append(toolbar);const journey=el('nav',undefined,'journey');journey.setAttribute('aria-label',c.pipelineTitle);(['home','runs','build','correct','categories'] as Page[]).forEach((step,i)=>{const link=el('a');link.href='#'+step+(step!=='home'&&step!=='categories'&&(activeRun||localStorage.getItem('workspace-active-run'))?'/'+encodeURIComponent(activeRun||localStorage.getItem('workspace-active-run')!):'');link.append(el('span',String(i+1).padStart(2,'0')),document.createTextNode(c.pipelineSteps[i]));if(page===step)link.setAttribute('aria-current','step');journey.append(link);});main.append(journey);const loading=el('div',c.loading,'loading-state');loading.setAttribute('role','status');main.append(loading);root.append(header,main);try{health=await api<Health>('/api/health');if(generation!==renderId)return;loading.remove();systemLink.textContent=health.status==='READY'?c.operationalStatus:c.setupStatus;systemLink.dataset.ready=String(health.status==='READY');if(health.project?.productName){configureProjectCopy(health.project);document.title=c.product;const brand=header.querySelector('.brand');if(brand)brand.textContent=c.product;for(const link of nav.querySelectorAll('a')){const key=link.hash.slice(1) as Page;link.replaceChildren(icon(key),document.createTextNode(c.nav[key]));}}if(health.signIn?.authenticated===false){nav.hidden=true;signInSetup(main);return;}if(requested==='monitor'){main.append(section(c.preparingRun,c.startingClassification));return;}if(page==='home')await home(main);else if(page==='runs')await runs(main,generation);else if(page==='build')await build(main);else if(page==='correct')await correct(main);else if(page==='categories')await categories(main,{request:api,onError:showError,onActivated:revision=>{void referenceLabels(main,revision,{request:api,onError:showError,onReady:()=>{localStorage.setItem('local-extraction-run',crypto.randomUUID());route('home');}}).catch(error=>showError(error,main));if(!correctionContext()){const next=section(c.nextStep,c.categoryActivated);next.append(button(c.startRun,()=>route('home'),true));main.append(next);}}});else if(page==='health')await healthPage(main);else help(main);}catch(error){loading.remove();systemLink.textContent=c.healthUnavailable;if(generation===renderId){if(page==='build')await build(main);else if(page==='correct')await correct(main);else if(page==='help')help(main);else if(page==='home')await home(main);showError(error);}}}
